    // \u6b64\u65f6\u4ecd\u53ef\u4ee5\u8bfb\u53d6\u670d\u52a1\u5668\u53d1\u9001\u7684\u6570\u636e\n        buffer := make([]byte, 1024)\n        n, err := conn.Read(buffer)\n        if err != nil {\n            fmt.Printf("\u8bfb\u53d6\u5230 %d \u5b57\u8282: %s\\n", n, string(buffer[:n]))\n        }\n        \n        // \u5173\u95ed\u8bfb\u65b9\u5411\n        tcpConn.CloseRead()\n    }\n}\n\n// \u68c0\u6d4b\u8fde\u63a5\u5173\u95ed\nfunc detectConnectionClose() {\n    conn, _ := net.Dial("tcp", "localhost:8080")\n    defer conn.Close()\n    \n    go func() {\n        buffer := make([]byte, 1024)\n        for {\n            n, err := conn.Read(buffer)\n            if err != nil {\n                if err == io.EOF {\n                    fmt.Println("\u5bf9\u65b9\u5173\u95ed\u4e86\u8fde\u63a5")\n                } else {\n                    fmt.Printf("\u8bfb\u53d6\u9519\u8bef: %v\\n", err)\n                }\n                return\n            }\n            fmt.Printf("\u63a5\u6536\u5230 %d \u5b57\u8282\\n", n)\n        }\n    }()\n    \n    time.Sleep(10 * time.Second)\n}\n'})}),"\n",(0,i.jsx)(e.h3,{id:"10-\u4ec0\u4e48\u60c5\u51b5\u4e0b\u4f1a\u51fa\u73b0\u5927\u91cf-close_wait-\u548c-time_wait-\u72b6\u6001\u5982\u4f55\u89e3\u51b3",children:"10. \u4ec0\u4e48\u60c5\u51b5\u4e0b\u4f1a\u51fa\u73b0\u5927\u91cf CLOSE_WAIT \u548c TIME_WAIT \u72b6\u6001\uff1f\u5982\u4f55\u89e3\u51b3\uff1f"}),"\n",(0,i.jsx)(e.p,{children:(0,i.jsx)(e.strong,{children:"CLOSE_WAIT \u72b6\u6001\u5206\u6790\uff1a"})}),"\n",(0,i.jsx)(e.mermaid,{value:"sequenceDiagram\n    participant Client as \u5ba2\u6237\u7aef\n    participant Server as \u670d\u52a1\u5668\u8fdb\u7a0b\n    \n    Client->>Server: \u6b63\u5e38\u6570\u636e\u4f20\u8f93\n    Note over Client: \u5ba2\u6237\u7aef\u51b3\u5b9a\u65ad\u5f00\u8fde\u63a5\n    Client->>Server: FIN (\u5173\u95ed\u8fde\u63a5)\n    Server--\x3e>Client: ACK (\u786e\u8ba4\u6536\u5230FIN)\n    Note over Server: \u8fdb\u5165 CLOSE_WAIT \u72b6\u6001\n    Note over Ser