nn.SetWriteBuffer(64 * 1024)  // 64KB \u5199\u7f13\u51b2\u533a\n    \n    // 3. \u8bbe\u7f6e Keep-Alive \u53c2\u6570\n    conn.SetKeepAlive(true)\n    conn.SetKeepAlivePeriod(30 * time.Second)\n    \n    // 4. \u8bbe\u7f6e\u8bfb\u5199\u8d85\u65f6\n    conn.SetReadDeadline(time.Now().Add(30 * time.Second))\n    conn.SetWriteDeadline(time.Now().Add(30 * time.Second))\n}\n'})}),"\n",(0,i.jsx)(e.p,{children:(0,i.jsx)(e.strong,{children:"\u9ad8\u6027\u80fd\u670d\u52a1\u5668\u6a21\u5f0f\uff1a"})}),"\n",(0,i.jsx)(e.pre,{children:(0,i.jsx)(e.code,{className:"language-go",children:"// 1. \u4f7f\u7528\u5de5\u4f5c\u6c60\u6a21\u5f0f\ntype WorkerPool struct {\n    workerCount int\n    jobQueue    chan net.Conn\n    workers     []*Worker\n}\n\ntype Worker struct {\n    id       int\n    jobQueue chan net.Conn\n    quit     chan bool\n}\n\nfunc (w *Worker) start() {\n    go func() {\n        for {\n            select {\n            case conn := <-w.jobQueue:\n                w.handleConnection(conn)\n            case <-w.quit:\n                return\n            }\n        }\n    }()\n}\n\nfunc (w *Worker) handleConnection(conn net.Conn) {\n    defer conn.Close()\n    \n    // \u9ad8\u6548\u7684\u6570\u636e\u5904\u7406\n    reader := bufio.NewReader(conn)\n    writer := bufio.NewWriter(conn)\n    \n    for {\n        line, err := reader.ReadString('\\n')\n        if err != nil {\n            break\n        }\n        \n        // \u5904\u7406\u6570\u636e\n        response := processData(line)\n        \n        writer.WriteString(response)\n        writer.Flush()\n    }\n}\n\n// 2. \u96f6\u62f7\u8d1d\u4f18\u5316\nfunc zeroCopyTransfer(dst net.Conn, src *os.File) error {\n    // \u5728 Linux \u4e0b\u53ef\u4ee5\u4f7f\u7528 sendfile \u7cfb\u7edf\u8c03\u7528\n    if tcpConn, ok := dst.(*net.TCPConn); ok {\n        file, err := tcpConn.File()\n        if err != nil {\n            return err\n        }\n        defer file.Close()\n        \n        // \u4f7f\u7528 splice/sendfile \u8fdb\u884c\u96f6\u62f7\u8d1d\u4f20\u8f93\n        return syscall.Sendfile(int(file.Fd()), int(src.Fd()), nil, 1024*1024)\n    }\n    \n    // \u56de\u9000\u5230\u666e\u901a\u62f7\u8d1d\n    _, err := io.Copy(dst, src)\n    return err\n}\n"})}),"\n",(0,i.jsx)(e.p,{children:(0,i.jsx)(e.strong,{children:"\u5185\u5b58\u4f18\u5316\uff1a"})}),"\n",(0,i.jsx)(e.pre,{children:(0,i.jsx)(e.code,{className:"language-go",children:"// 3. \u5bf9\u8c61\u6c60\u590d\u7528\nvar bufferPool = sync.Pool{\n    New: func() interface{} {\n        return make([]byte, 32*1024) // 32KB \u7f13\u51b2\u533a\n    },\n}\n\nfunc efficientHandler(conn net.Conn) {\n    defer conn.Close()\n    \n    // \u4ece\u6c60\u4e2d\u83b7\u53d6\u7f13\u51b2\u533a\n    buffer := bufferPool.Get().([]byte)\n    defer bufferPool.Put(buffer) // \u4f7f\u7528\u5b8c\u6bd5\u540e\u5f52\u8fd8\n    \n    for {\n        n, err := conn.Read(buffer)\n        if err != nil {\n            break\n        }\n        \n        // \u5904\u7406\u6570\u636e\n        processBuffer(buffer[:n])\n        \n        // \u5199\u56de\u54cd\u5e94\n        conn.Write(buffer[:n])\n    }\n}\n\n// 4. \u6279\u91cf\u5904\u7406\u4f18\u5316\nfunc batchProcessor(connections []net.Conn) {\n    // \u4f7f\u7528 epoll \u6216\u7c7b\u4f3c\u673a\u5236\u6279\u91cf\u5904\u7406\u591a\u4e2a\u8fde\u63a5\n    fds := make([]int, len(connections))\n    for i, conn := range connections {\n        if tcpConn, ok := conn.(*net.TCPConn); ok {\n            file, _ := tcpConn.File()\n            fds[i] = int(file.Fd())\n        }\n    }\n    \n    // \u6279\u91cf\u68c0\u67e5\u53ef\u8bfb\u72b6\u6001\uff08\u7b80\u5316\u793a\u4f8b\uff09\n    readyFds := epollWait(fds, 1000) // \u7b49\u5f85\u6700\u591a1\u79d2\n    \n    for _, fd := range readyFds {\n        // \u5904\u7406\u5c31\u7eea\u7684\u8fde\u63a5\n        handleReadyConnection(fd)\n    }\n}\n"})}),"\n",(0,i.jsx)(e.h3,{id:"13-\u5982\u4f55\u5b9e\u73b0\u4e00\u4e2a\u652f\u6301\u767e\u4e07\u5e76\u53d1\u8fde\u63a5\u7684-tcp-\u670d\u52a1\u5668",children:"13. \u5982\u4f55\u5b9e\u73b0\u4e00\u4e2a\u652f\u6301\u767e\u4e07\u5e76\u53d1\u8fde\u63a5\u7684 TCP \u670d\u52a1\u5668\uff1f"}),"\n",(0,i.jsx)(e.p,{children:(0,i.jsx)(e.strong,{children:"\u7cfb\u7edf\u7ea7\u4f18\u5316\uff1a"})}),"\n",(0,i.jsx)(e.pre,{children:(0,i.jsx)(e.code,{className:"language-bash",children:'# 1. \u7cfb\u7edf\u53c2\u6570\u8c03\u4f18\n# \u589e\u52a0\u6587\u4ef6\u63cf\u8ff0\u7b26\u9650\u5236\necho "* soft nofile 1048576" >> /etc/security/limits.conf\necho "* hard nofile 1048576" >> /etc/security/limits.conf\n\n# TCP \u53c2\u6570\u4f18\u5316\necho 1 > /proc/sys/net/ipv4/tcp_tw_reuse\necho 1 > /proc/sys/net/ipv4/tcp_tw_recycle\necho 32768 > /proc/sys/net/core/somaxconn\necho 262144 > /proc/sys/net/core/netdev_max_backlog\n\n# \u5185\u5b58\u53c2\u6570\u8c03\u4f18\necho "1024 87380 16777216" > /proc/sys/net/ipv4/tcp_rmem\necho "1024 65536 16777216" > /proc/sys/net/ipv4/tcp_wmem\n'})}),"\n",(0,i.jsx)(e.p,{children:(0,i.jsx)(e.strong,{children:"Go \u7a0b\u5e8f\u67b6\u6784\uff1a"})}),"\n",(0,i.jsx)(e.pre,{children:(0,i.jsx)(e.code,{className:"language-go",children:'package main\n\nimport (\n    "context"\n    "fmt"\n    "log"\n    "net"\n    "runtime"\n    "sync/atomic"\n    "time"\n)\n\n// \u767e\u4e07\u8fde\u63a5\u670d\u52a1\u5668\ntype MillionConnServer struct {\n    listener        net.Listener\n    connCount      int64\n    messageCount   int64\n    workerPool     *WorkerPool\n    ctx            context.Context\n    cancel         context.CancelFunc\n}\n\nfunc NewMillionConnServer(addr string) *MillionConnServer {\n    ctx, cancel := context.WithCancel(context.Background())\n    \n    return &MillionConnServer{\n        workerPool: NewWorkerPool(runtime.NumCPU() * 2),\n        ctx:        ctx,\n        cancel:     cancel,\n    }\n}\n\nfunc (s *MillionConnServer) Start(addr string) error {\n    listener, err := net.Listen("tcp", addr)\n    if err != nil {\n        return err\n    }\n    s.listener = listener\n    \n    // \u542f\u52a8\u5de5\u4f5c\u6c60\n    s.workerPool.Start()\n    \n    // \u542f\u52a8\u76d1\u63a7\n    go s.startMonitoring()\n    \n    // \u63a5\u53d7\u8fde\u63a5\u5faa\u73af\n    for {\n        select {\n        case <-s.ctx.Done():\n            return nil\n        default:\n            conn, err := listener.Accept()\n            if err != nil {\n                continue\n            }\n            \n            // \u4f18\u5316\u8fde\u63a5\u53c2\u6570\n            if tcpConn, ok := conn.(*net.TCPConn); ok {\n                tcpConn.SetNoDelay(true)\n                tcpConn.SetKeepAlive(true)\n                tcpConn.SetKeepAlivePeriod(60 * time.Second)\n            }\n            \n            atomic.AddInt64(&s.connCount, 1)\n            \n            // \u63d0\u4ea4\u5230\u5de5\u4f5c\u6c60\n            s.workerPool.Submit(conn)\n        }\n    }\n}\n\nfunc (s *MillionConnServer) startMonitoring() {\n    ticker := time.NewTicker(10 * time.Second)\n    defer ticker.Stop()\n    \n    for {\n        select {\n        case <-ticker.C:\n            connCount := atomic.LoadInt64(&s.connCount)\n            msgCount := atomic.LoadInt64(&s.messageCount)\n            \n            var m runtime.MemStats\n            runtime.ReadMemStats(&m)\n            \n            fmt.Printf("\u8fde\u63a5\u6570: %d, \u6d88\u606f\u6570: %d, \u5185\u5b58: %.2f MB, Goroutines: %d\\n",\n                connCount, msgCount,\n                float64(m.Alloc)/1024/1024,\n                runtime.NumGoroutine())\n                \n        case <-s.ctx.Done():\n            return\n        }\n    }\n}\n\n// \u9ad8\u6548\u7684\u5de5\u4f5c\u6c60\u5b9e\u73b0\ntype WorkerPool struct {\n    workerCount int\n    jobQueue    chan net.Conn\n    workers     []*Worker\n}\n\nfunc NewWorkerPool(workerCount int) *WorkerPool {\n    return &WorkerPool{\n        workerCount: workerCount,\n        jobQueue:    make(chan net.Conn, workerCount*100), // \u7f13\u51b2\u961f\u5217\n    }\n}\n\nfunc (wp *WorkerPool) Start() {\n    wp.workers = make([]*Worker, wp.workerCount)\n    \n    for i := 0; i < wp.workerCount; i++ {\n        worker := &Worker{\n            id:       i,\n            jobQueue: wp.jobQueue,\n            quit:     make(chan bool),\n        }\n        wp.workers[i] = worker\n        worker.start()\n    }\n}\n\nfunc (wp *WorkerPool) Submit(conn net.Conn) {\n    select {\n    case wp.jobQueue <- conn:\n    default:\n        // \u961f\u5217\u6ee1\u4e86\uff0c\u76f4\u63a5\u5173\u95ed\u8fde\u63a5\n        conn.Close()\n    }\n}\n\ntype Worker struct {\n    id       int\n    jobQueue chan net.Conn\n    quit     chan bool\n}\n\nfunc (w *Worker) start() {\n    go func() {\n        for {\n            select {\n            case conn := <-w.jobQueue:\n                w.handleConnection(conn)\n            case <-w.quit:\n                return\n            }\n        }\n    }()\n}\n\nfunc (w *Worker) handleConnection(conn net.Conn) {\n    defer conn.Close()\n    \n    // \u8bbe\u7f6e\u8bfb\u8d85\u65f6\n    conn.SetReadDeadline(time.Now().Add(30 * time.Second))\n    \n    buffer := make([]byte, 1024)\n    for {\n        n, err := conn.Read(buffer)\n        if err != nil {\n            break\n        }\n        \n        // \u7b80\u5355\u56de\u663e\n        conn.Write(buffer[:n])\n        \n        // \u91cd\u7f6e\u8d85\u65f6\n        conn.SetReadDeadline(time.Now().Add(30 * time.Second))\n    }\n}\n\n// \u538b\u529b\u6d4b\u8bd5\u5ba2\u6237\u7aef\nfunc stressTestClient(serverAddr string, clientCount int) {\n    sem := make(chan struct{}, 1000) // \u9650\u5236\u5e76\u53d1\u8fde\u63a5\u6570\n    \n    for i := 0; i < clientCount; i++ {\n        go func(id int) {\n            sem <- struct{}{} // \u83b7\u53d6\u8bb8\u53ef\n            defer func() { <-sem }() // \u91ca\u653e\u8bb8\u53ef\n            \n            conn, err := net.Dial("tcp", serverAddr)\n            if err != nil {\n                log.Printf("\u5ba2\u6237\u7aef %d \u8fde\u63a5\u5931\u8d25: %v", id, err)\n                return\n            }\n            defer conn.Close()\n            \n            // \u53d1\u9001\u6d4b\u8bd5\u6570\u636e\n            testData := fmt.Sprintf("Hello from client %d\\n", id)\n            conn.Write([]byte(testData))\n            \n            // \u8bfb\u53d6\u54cd\u5e94\n            buffer := make([]byte, 1024)\n            n, err := conn.Read(buffer)\n            if err != nil {\n                log.Printf("\u5ba2\u6237\u7aef %d \u8bfb\u53d6\u5931\u8d25: %v", id, err)\n                return\n            }\n            \n            log.Printf("\u5ba2\u6237\u7aef %d \u6536\u5230\u54cd\u5e94: %s", id, string(buffer[:n]))\n            \n            // \u4fdd\u6301\u8fde\u63a5\u4e00\u6bb5\u65f6\u95f4\n            time.Sleep(time.Minute)\n        }(i)\n        \n        // \u63a7\u5236\u8fde\u63a5\u5efa\u7acb\u901f\u5ea6\n        if i%1000 == 0 {\n            time.Sleep(100 * time.Millisecond)\n        }\n    }\n}\n\nfunc main() {\n    server := NewMillionConnServer(":8080")\n    \n    go func() {\n        log.Println("\u542f\u52a8\u538b\u529b\u6d4b\u8bd5\u5ba2\u6237\u7aef...")\n        time.Sleep(2 * time.Second)\n        stressTestClient("localhost:8080", 100000) // 10\u4e07\u8fde\u63a5\u6d4b\u8bd5\n    }()\n    \n    log.Println("\u542f\u52a8\u767e\u4e07\u8fde\u63a5\u670d\u52a1\u5668...")\n    if err := server.Start(":8080"); err != nil {\n        log.Fatal(err)\n    }\n}\n'})}),"\n",(0,i.jsx)(e.p,{children:(0,i.jsx)(e.strong,{children:"\u5173\u952e\u4f18\u5316\u70b9\uff1a"})}),"\n",(0,i.jsxs)(e.ol,{children:["\n",(0,i.jsxs)(e.li,{children:["\n",(0,i.jsxs)(e.p,{children:[(0,i.jsx)(e.strong,{children:"\u5185\u5b58\u4f18\u5316"}),"\uff1a"]}),"\n",(0,i.jsxs)(e.ul,{children:["\n",(0,i.jsx)(e.li,{children:"\u4f7f\u7528\u5bf9\u8c61\u6c60\u590d\u7528\u7f13\u51b2\u533a"}),"\n",(0,i.jsx)(e.li,{children:"\u63a7\u5236 Goroutine \u6570\u91cf"}),"\n",(0,i.jsx)(e.li,{children:"\u53ca\u65f6\u91ca\u653e\u4e0d\u9700\u8981\u7684\u8d44\u6e90"}),"\n"]}),"\n"]}),"\n",(0,i